// Package tourgogen writes internal/tourgo's linked_gen.go: the adapters of
// every `go` binding a tour block declares, generated by internal/ffirun
// from the block's declarations and the Go it binds. See internal/tourgo.
package tourgogen

import (
	"bytes"
	"fmt"
	goformat "go/format"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"github.com/nomi-language/nomi/internal/doctest"
	"github.com/nomi-language/nomi/internal/ffirun"
	"github.com/nomi-language/nomi/internal/tourgo"
	"github.com/nomi-language/nomi/internal/virtualproject"
)

// modulePath is the compiler module, where a tour block's Go package lives:
// internal/tourgo/<package>.
const modulePath = "github.com/nomi-language/nomi"

// GoDir is the folder, under the repository root, that holds the Go packages
// the tour's blocks bind, one folder per package.
const GoDir = "internal/tourgo"

// Block is a tour block that declares a `gopkg`.
type Block struct {
	// Name is the block as the generated file names it: its chapter and
	// its place among the chapter's blocks that declare a `gopkg`
	// (`ffi-and-dynamic.md, block 1`), which a line moved above it keeps.
	Name string
	// Line is the line of its opening fence.
	Line int
	Code string
}

// Blocks is every ```nomi-run block of the tour's chapters under root (the
// repository) that declares a `gopkg`, in chapter and line order.
func Blocks(root string) ([]Block, error) {
	docs := filepath.Join(root, "tour", "src", "content", "docs")
	chapters, err := filepath.Glob(filepath.Join(docs, "*.md"))
	if err != nil {
		return nil, err
	}
	sort.Strings(chapters)
	gopkg := regexp.MustCompile(`(?m)^gopkg\s`)
	var out []Block
	for _, chapter := range chapters {
		data, err := os.ReadFile(chapter)
		if err != nil {
			return nil, err
		}
		n := 0
		for _, b := range doctest.ExtractBlocks(string(data), "nomi-run") {
			if gopkg.MatchString(b.Code) {
				n++
				out = append(out, Block{Name: fmt.Sprintf("%s, block %d", filepath.Base(chapter), n), Line: b.Line, Code: b.Code})
			}
		}
	}
	return out, nil
}

// GoFiles is a block's Go files, by their name in the block, with their
// text as the block holds it.
func GoFiles(code string) (map[string]string, error) {
	p, err := virtualproject.FromMarkedSource(code)
	if err != nil {
		return nil, err
	}
	out := map[string]string{}
	for name, text := range p.DataFiles {
		if strings.HasSuffix(name, ".go") {
			out[name] = text
		}
	}
	return out, nil
}

var packageClause = regexp.MustCompile(`(?m)^package\s+(\w+)`)

// GoPackageOf is the package a Go file's text declares.
func GoPackageOf(text string) string {
	if m := packageClause.FindStringSubmatch(text); m != nil {
		return m[1]
	}
	return ""
}

// LinkedPath is where the tree keeps a block's Go file name of package pkg,
// relative to root.
func LinkedPath(pkg, name string) string {
	return filepath.Join(GoDir, pkg, filepath.Base(name))
}

// File is linked_gen.go for the tour under root, staging each block in a
// directory under work.
func File(root, work string) ([]byte, error) {
	blocks, err := Blocks(root)
	if err != nil {
		return nil, err
	}
	goMod, err := os.ReadFile(filepath.Join(root, "go.mod"))
	if err != nil {
		return nil, err
	}
	goLine := regexp.MustCompile(`(?m)^go .*$`).FindString(string(goMod))
	imports := map[string]string{}
	var decls, table bytes.Buffer
	seen := map[string]string{}
	for i, b := range blocks {
		p, err := virtualproject.FromMarkedSource(b.Code)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", b.Name, err)
		}
		dir := filepath.Join(work, fmt.Sprintf("block%d", i))
		write := func(name, text string) error {
			path := filepath.Join(dir, filepath.FromSlash(name))
			if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
				return err
			}
			return os.WriteFile(path, []byte(text), 0o644)
		}
		entry := p.EntryName + ".nomi"
		if err := write(entry, p.EntrySource); err != nil {
			return nil, err
		}
		for name, text := range p.VirtualFiles {
			if !strings.HasSuffix(name, ".toml") {
				name += ".nomi"
			}
			if err := write(name, text); err != nil {
				return nil, err
			}
		}
		goFiles, err := GoFiles(b.Code)
		if err != nil {
			return nil, err
		}
		// The block's Go is compiled from the tree, as the page shows it
		// (tourgo's TestTourGoFilesAreTheLinkedSources holds the two
		// equal), and its package is the module the block's `gopkg` names.
		local := map[string]bool{}
		for name, text := range goFiles {
			pkg := GoPackageOf(text)
			if pkg == "" {
				return nil, fmt.Errorf("%s: %s has no package clause", b.Name, name)
			}
			src, err := os.ReadFile(filepath.Join(root, LinkedPath(pkg, name)))
			if err != nil {
				return nil, fmt.Errorf("%s: its Go file %s is compiled from %s: %w", b.Name, name, LinkedPath(pkg, name), err)
			}
			if err := write(name, string(src)); err != nil {
				return nil, err
			}
			local[pkg] = true
		}
		if len(local) > 1 {
			return nil, fmt.Errorf("%s: its Go files declare %d packages; a block binds at most one of its own", b.Name, len(local))
		}
		for pkg := range local {
			if err := write("go.mod", "module "+pkg+"\n\n"+goLine+"\n"); err != nil {
				return nil, err
			}
		}
		prefix := fmt.Sprintf("tourBlock%d", i)
		l, err := ffirun.LinkedAdapters(filepath.Join(dir, entry), prefix)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", b.Name, err)
		}
		for path, alias := range l.Imports {
			if local[path] {
				path = modulePath + "/" + filepath.ToSlash(GoDir) + "/" + path
			}
			if other, ok := imports[path]; ok && other != alias {
				return nil, fmt.Errorf("%s: the adapters import %s as %s, and another block's as %s", b.Name, path, alias, other)
			}
			imports[path] = alias
		}
		fmt.Fprintf(&decls, "\n// %s\n\n%s\n", b.Name, l.Decls)
		bindings := tourgo.GoBindings(p.EntryName, p.EntrySource, p.VirtualFiles)
		for _, lb := range l.Bindings {
			symbol := lb.ImportPath + "." + lb.Func
			var match *tourgo.Binding
			for j := range bindings {
				if bindings[j].ImportPath == lb.ImportPath && bindings[j].Func == lb.Func {
					match = &bindings[j]
					break
				}
			}
			if match == nil {
				return nil, fmt.Errorf("%s: tourgo.GoBindings finds no declaration that binds %s", b.Name, symbol)
			}
			if first, dup := seen[symbol]; dup {
				return nil, fmt.Errorf("%s: %s is bound in %s too; the tour links each Go function once", b.Name, symbol, first)
			}
			seen[symbol] = b.Name
			fmt.Fprintf(&table, "\t{importPath: %s, fn: %s, decl: %s, shape: %s, file: %s, block: %d, bind: %sBind, key: %s},\n",
				strconv.Quote(lb.ImportPath), strconv.Quote(lb.Func), strconv.Quote(match.Decl),
				strconv.Quote(match.Shape), strconv.Quote(match.File), i, prefix, strconv.Quote(lb.Key))
		}
	}
	var out bytes.Buffer
	out.WriteString("// Code generated by go generate ./internal/tourgo; DO NOT EDIT.\n\n")
	out.WriteString("// The adapters of every `go` binding a tour block declares, generated by\n")
	out.WriteString("// internal/ffirun from the block. See tourgo.go.\n\n")
	out.WriteString("package tourgo\n\n")
	paths := make([]string, 0, len(imports))
	for path := range imports {
		paths = append(paths, path)
	}
	sort.Strings(paths)
	out.WriteString("import (\n")
	for _, path := range paths {
		fmt.Fprintf(&out, "\t%s %s\n", imports[path], strconv.Quote(path))
	}
	out.WriteString(")\n")
	out.Write(decls.Bytes())
	out.WriteString("\n// linked is every Go function the tour links.\nvar linked = []linkedFunc{\n")
	out.Write(table.Bytes())
	out.WriteString("}\n")
	return render("linked_gen.go", out.Bytes())
}

// render is a generated file's text, formatted.
func render(name string, text []byte) ([]byte, error) {
	formatted, err := goformat.Source(text)
	if err != nil {
		return nil, fmt.Errorf("formatting %s: %w\n%s", name, err, text)
	}
	return formatted, nil
}

// ModulesFileName is the file ModulesFile writes, in internal/tourgo.
const ModulesFileName = "linked_modules_gen.go"

// ModulesFile is internal/tourgo's linked_modules_gen.go: the adapters of
// every tour module's bindings, and linkedModules, generated from each
// module's directory in the tree (moduleAdapters). The file imports each
// module's Go package, which the compiler's go.mod does not require, so it
// is built for js alone, in the tourgo.GoWork workspace; elsewhere
// modules_native.go declares linkedModules empty.
func ModulesFile(root, work string) ([]byte, error) {
	imports := map[string]string{}
	var decls, modules bytes.Buffer
	for i, m := range tourgo.Modules {
		prefix := fmt.Sprintf("tourModule%d", i)
		l, err := moduleAdapters(root, work, m, prefix)
		if err != nil {
			return nil, fmt.Errorf("the tour module %s: %w", m.Name, err)
		}
		for path, alias := range l.Imports {
			if other, ok := imports[path]; ok && other != alias {
				return nil, fmt.Errorf("the tour module %s: its adapters import %s as %s, and another module's as %s", m.Name, path, alias, other)
			}
			imports[path] = alias
		}
		fmt.Fprintf(&decls, "\n// The tour module %s (%s)\n\n%s\n", m.Name, m.Path, l.Decls)
		fmt.Fprintf(&modules, "\t{module: %s, bind: %sBind},\n", strconv.Quote(m.Path), prefix)
	}
	var out bytes.Buffer
	out.WriteString("// Code generated by go generate ./internal/tourgo; DO NOT EDIT.\n\n")
	out.WriteString("//go:build js\n\n")
	out.WriteString("// The adapters of every tour module's bindings, generated by\n")
	out.WriteString("// internal/ffirun from the module's directory in the tree. Built in the\n")
	out.WriteString("// tour.work workspace. See modules.go.\n\n")
	out.WriteString("package tourgo\n\n")
	paths := make([]string, 0, len(imports))
	for path := range imports {
		paths = append(paths, path)
	}
	sort.Strings(paths)
	out.WriteString("import (\n")
	for _, path := range paths {
		fmt.Fprintf(&out, "\t%s %s\n", imports[path], strconv.Quote(path))
	}
	out.WriteString(")\n")
	out.Write(decls.Bytes())
	out.WriteString("\n// linkedModules is the adapters of every tour module's bindings.\nvar linkedModules = []linkedModule{\n")
	out.Write(modules.Bytes())
	out.WriteString("}\n")
	return render(ModulesFileName, out.Bytes())
}

// moduleAdapters generates the adapters of a tour module's bindings, named
// with prefix, from the module's directory under root: a project staged
// under work requires the module and replaces it with that directory, as a
// program's dependency is, and ffirun reads the module's bindings and its
// Go package from there.
func moduleAdapters(root, work string, m tourgo.Module, prefix string) (*ffirun.Linked, error) {
	dir, err := filepath.Abs(filepath.Join(root, filepath.FromSlash(m.Dir)))
	if err != nil {
		return nil, err
	}
	goMod, err := os.ReadFile(filepath.Join(root, "go.mod"))
	if err != nil {
		return nil, err
	}
	goLine := regexp.MustCompile(`(?m)^go .*$`).FindString(string(goMod))
	stage := filepath.Join(work, "module-"+m.Name)
	if err := os.MkdirAll(stage, 0o755); err != nil {
		return nil, err
	}
	project := fmt.Sprintf("module tour\n\n%s\n\nrequire %s v0.0.0\n\nreplace %s => %s\n", goLine, m.Path, m.Path, dir)
	if err := os.WriteFile(filepath.Join(stage, "go.mod"), []byte(project), 0o644); err != nil {
		return nil, err
	}
	entry := filepath.Join(stage, "main.nomi")
	if err := os.WriteFile(entry, []byte("fn main() {\n}\n"), 0o644); err != nil {
		return nil, err
	}
	return ffirun.LinkedAdapters(entry, prefix)
}

// SourcesFileName is the file SourcesFile writes, in internal/tourgo.
const SourcesFileName = "modules_sources_gen.go"

// SourcesFile is internal/tourgo's modules_sources_gen.go: the text of each
// tour module's nomi.toml and Nomi files, its tests left out, read from
// its directory under root. A tour module is its own Go module, nested in
// this repository, so the compiler's module cannot embed its files; the
// tour's wasm carries them from this file.
func SourcesFile(root string) ([]byte, error) {
	var out bytes.Buffer
	out.WriteString("// Code generated by go generate ./internal/tourgo; DO NOT EDIT.\n\n")
	out.WriteString("// The nomi.toml and Nomi files of every tour module, its tests left out,\n")
	out.WriteString("// from the module's directory in the tree. See modules.go.\n\n")
	out.WriteString("package tourgo\n\n")
	out.WriteString("var moduleSources = map[string]map[string]string{\n")
	for _, m := range tourgo.Modules {
		files, err := ModuleSources(filepath.Join(root, filepath.FromSlash(m.Dir)))
		if err != nil {
			return nil, fmt.Errorf("the tour module %s: %w", m.Name, err)
		}
		fmt.Fprintf(&out, "\t%s: {\n", strconv.Quote(m.Name))
		for _, name := range files {
			text, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(m.Dir), filepath.FromSlash(name)))
			if err != nil {
				return nil, err
			}
			fmt.Fprintf(&out, "\t\t%s: %s,\n", strconv.Quote(name), strconv.Quote(string(text)))
		}
		out.WriteString("\t},\n")
	}
	out.WriteString("}\n")
	return render(SourcesFileName, out.Bytes())
}

// ModuleSources is the paths, in dir, of the files of the Nomi module at
// dir that a program importing it reads: its nomi.toml and its Nomi files,
// not its tests, nor any file under a directory that holds a go.mod or a
// nomi.toml of its own, or whose name starts with `.` or is testdata.
func ModuleSources(dir string) ([]string, error) {
	var out []string
	err := filepath.WalkDir(dir, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(dir, path)
		if err != nil {
			return err
		}
		if d.IsDir() {
			if rel == "." {
				return nil
			}
			if strings.HasPrefix(d.Name(), ".") || d.Name() == "testdata" || isFile(filepath.Join(path, "go.mod")) || isFile(filepath.Join(path, "nomi.toml")) {
				return filepath.SkipDir
			}
			return nil
		}
		name := d.Name()
		if rel == "nomi.toml" || (strings.HasSuffix(name, ".nomi") && !strings.HasSuffix(name, "_test.nomi")) {
			out = append(out, filepath.ToSlash(rel))
		}
		return nil
	})
	sort.Strings(out)
	return out, err
}

func isFile(path string) bool {
	info, err := os.Stat(path)
	return err == nil && !info.IsDir()
}
